// Audio: buses (ambience, sfx, music, voice), ducking under voice, silent-safe.
// Files are only requested if they exist (manifest generated by the vite plugin), so missing audio
// never produces a network error. Missing SFX fall back to small synthesized sounds (no TTS, ever).
import manifest from 'virtual:audio-manifest'
import { config } from '../content/config'
import { onTick } from '../engine/clock'
import { useRide } from '../engine/store'
import { lineTimes } from '../engine/timeline'
import { setLiveActivity } from '../engine/voiceActivity'
import { assets } from '../content/assets'

const has = (file: string | null | undefined): file is string => !!file && (manifest as string[]).includes(file.replace(/^\/?audio\//, ''))

let ctx: AudioContext | null = null
let master: GainNode, buses: Record<'amb' | 'sfx' | 'music' | 'voice', GainNode>
const buffers = new Map<string, AudioBuffer>()

export function unlockAudio() {
  if (ctx) { void ctx.resume(); return }
  try {
    ctx = new AudioContext()
  } catch { return }
  master = ctx.createGain()
  master.connect(ctx.destination)
  buses = { amb: gain(0.5), sfx: gain(0.7), music: gain(0.5), voice: gain(1) }
  startLoops()
  onTick(handleTick)
  useRide.subscribe((s) => { master.gain.setTargetAtTime(s.muted ? 0 : 1, ctx!.currentTime, 0.05) })
}

function gain(v: number) {
  const g = ctx!.createGain()
  g.gain.value = v
  g.connect(master)
  return g
}

async function load(file: string) {
  if (!ctx || !has(file)) return null
  if (buffers.has(file)) return buffers.get(file)!
  try {
    const res = await fetch(`/audio/${file}`)
    const buf = await ctx.decodeAudioData(await res.arrayBuffer())
    buffers.set(file, buf)
    return buf
  } catch { return null }
}

// ───────────── SFX ─────────────

export type Sfx = 'flagdown' | 'tick' | 'snap' | 'horn' | 'hornShort'

export async function sfx(name: Sfx) {
  if (!ctx || ctx.state !== 'running') return
  const buf = await load(assets.audio.sfx[name])
  if (buf) {
    const src = ctx.createBufferSource()
    src.buffer = buf
    src.connect(buses.sfx)
    src.start()
    return
  }
  synth(name)
}

function synth(name: Sfx) {
  const c = ctx!, now = c.currentTime
  const env = (g: GainNode, a: number, peak: number, d: number) => {
    g.gain.setValueAtTime(0, now)
    g.gain.linearRampToValueAtTime(peak, now + a)
    g.gain.exponentialRampToValueAtTime(0.0001, now + a + d)
  }
  const tone = (type: OscillatorType, f: number, at: number, dur: number, peak: number) => {
    const o = c.createOscillator(), g = c.createGain()
    o.type = type
    o.frequency.value = f
    o.connect(g).connect(buses.sfx)
    g.gain.setValueAtTime(0, now + at)
    g.gain.linearRampToValueAtTime(peak, now + at + 0.005)
    g.gain.exponentialRampToValueAtTime(0.0001, now + at + dur)
    o.start(now + at)
    o.stop(now + at + dur + 0.05)
  }
  if (name === 'tick') tone('sine', 2200, 0, 0.03, 0.05)
  if (name === 'snap') { tone('triangle', 1400, 0, 0.06, 0.12); tone('sine', 2800, 0.02, 0.08, 0.06) }
  if (name === 'flagdown') { noiseBurst(0.04, 0.4); tone('square', 1760, 0.18, 0.22, 0.08) }
  if (name === 'horn' || name === 'hornShort') {
    const dur = name === 'horn' ? 0.9 : 0.25
    for (const f of [415, 440, 466]) {
      const o = c.createOscillator(), g = c.createGain()
      o.type = 'sawtooth'
      o.frequency.value = f
      o.connect(g).connect(buses.sfx)
      env(g, 0.02, 0.06, dur)
      o.start(now)
      o.stop(now + dur + 0.1)
    }
  }
}

function noiseBuffer(seconds: number) {
  const c = ctx!
  const buf = c.createBuffer(1, c.sampleRate * seconds, c.sampleRate)
  const d = buf.getChannelData(0)
  for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1
  return buf
}

function noiseBurst(dur: number, peak: number) {
  const c = ctx!, src = c.createBufferSource(), g = c.createGain(), f = c.createBiquadFilter()
  src.buffer = noiseBuffer(dur + 0.05)
  f.type = 'highpass'
  f.frequency.value = 2000
  src.connect(f).connect(g).connect(buses.sfx)
  g.gain.setValueAtTime(peak, c.currentTime)
  g.gain.exponentialRampToValueAtTime(0.0001, c.currentTime + dur)
  src.start()
}

// ───────────── loops: engine + rain + ambience ─────────────

let engineOsc: OscillatorNode, engineGain: GainNode, rainGain: GainNode
const ambSources = new Map<string, { gain: GainNode }>()

function startLoops() {
  const c = ctx!
  // engine: synthesized two-stroke-ish hum (replaced by engine loops if provided)
  engineOsc = c.createOscillator()
  engineOsc.type = 'sawtooth'
  engineOsc.frequency.value = 38
  const lp = c.createBiquadFilter()
  lp.type = 'lowpass'
  lp.frequency.value = 180
  engineGain = c.createGain()
  engineGain.gain.value = 0
  engineOsc.connect(lp).connect(engineGain).connect(buses.amb)
  engineOsc.start()
  // rain: filtered noise
  const rain = c.createBufferSource()
  rain.buffer = noiseBuffer(2)
  rain.loop = true
  const bp = c.createBiquadFilter()
  bp.type = 'bandpass'
  bp.frequency.value = 3000
  bp.Q.value = 0.4
  rainGain = c.createGain()
  rainGain.gain.value = 0
  rain.connect(bp).connect(rainGain).connect(buses.amb)
  rain.start()
  // recorded ambience beds per act (only if present)
  for (const [act, file] of Object.entries(assets.audio.ambience)) {
    void load(file).then((buf) => {
      if (!buf || !ctx) return
      const src = ctx.createBufferSource(), g = ctx.createGain()
      src.buffer = buf
      src.loop = true
      g.gain.value = 0
      src.connect(g).connect(buses.amb)
      src.start()
      ambSources.set(act, { gain: g })
    })
  }
}

// ───────────── voice tracks ─────────────

const voiceEls = new Map<string, HTMLAudioElement>()
let analyser: AnalyserNode | null = null
const levels = new Uint8Array(256)

function voiceFor(lineId: string, file: string) {
  let el = voiceEls.get(lineId)
  if (!el) {
    el = new Audio(`/audio/${file.replace(/^\/?audio\//, '')}`)
    el.preload = 'auto'
    voiceEls.set(lineId, el)
    try {
      const src = ctx!.createMediaElementSource(el)
      if (!analyser) {
        analyser = ctx!.createAnalyser()
        analyser.fftSize = 512
        analyser.connect(buses.voice)
      }
      src.connect(analyser)
    } catch { /* already connected */ }
  }
  return el
}

function analyserLevel() {
  if (!analyser) return 0
  analyser.getByteTimeDomainData(levels)
  let sum = 0
  for (const v of levels) sum += ((v - 128) / 128) ** 2
  return Math.min(1, Math.sqrt(sum / levels.length) * 5)
}

// ───────────── tick ─────────────

function handleTick(t: number, prev: number, seeked: boolean) {
  if (!ctx) return
  const s = useRide.getState()
  const f = s.frame
  const now = ctx.currentTime
  const running = s.playing && !s.overlay

  // edge-triggered SFX (only when playing forward, never on seeks)
  if (!seeked && t > prev && running) {
    if (prev < config.flagDownAt && t >= config.flagDownAt) void sfx('flagdown')
    for (const w of s.ride.counted) if (w.t > prev && w.t <= t && !hasVoice(w.lineId)) void sfx('tick')
    for (const l of s.ride.phoneLines) { const c = lineTimes(l).cleanAt; if (c > prev && c <= t) void sfx('snap') }
    if (prev < 1.5 && t >= 1.5) void sfx('hornShort')
    if (prev < 2 && t >= 2) void sfx('hornShort')
  }

  // engine follows speed; silent after arrival (139)
  const engineOn = t < 139 && f.scene.id !== 'voice' ? 1 : f.scene.id === 'voice' ? 0.3 : 0
  engineOsc.frequency.setTargetAtTime(34 + f.speed * 3.2 + f.activity * 6, now, 0.1)
  engineGain.gain.setTargetAtTime(running ? engineOn * (0.05 + f.activitySmooth * 0.06) : 0, now, 0.2)
  const raining = f.act === 'rain' || (f.scene.id === 'build' && t > 58) || (f.scene.id === 'reroute' && t < 98)
  rainGain.gain.setTargetAtTime(running && raining ? (f.scene.id === 'reroute' ? 0.05 : 0.12) : 0, now, 0.6)

  // ducking: beds drop under voice
  const duck = 1 - Math.min(0.55, f.activity * 0.55)
  buses.music.gain.setTargetAtTime(0.5 * duck, now, 0.15)
  for (const [act, a] of ambSources) a.gain.gain.setTargetAtTime(running && act === f.act ? 0.6 * duck : 0, now, 0.8)

  // voice tracks (after import-whisper fills line.audio)
  let liveFrom: HTMLAudioElement | null = null
  for (const l of s.ride.lines) {
    const file = l.audioByAddress?.[s.address] ?? l.audio
    if (!has(file)) continue
    const el = voiceFor(l.id, file)
    const local = t - l.start
    const inside = local >= 0 && local < (el.duration || l.wordEnd - l.start + 0.5)
    if (inside && running) {
      if (Math.abs(el.currentTime - local) > 0.15) el.currentTime = local
      el.playbackRate = s.rate
      if (el.paused) void el.play().catch(() => {})
      liveFrom = el
    } else if (!el.paused) el.pause()
  }
  setLiveActivity(liveFrom ? analyserLevel : null)
}

const hasVoice = (lineId: string) => {
  const l = useRide.getState().ride.lines.find((x) => x.id === lineId)
  return !!l && has(l.audioByAddress?.[useRide.getState().address] ?? l.audio)
}
